import sys
from collections import deque

def bfs(n, start, target, graph):
    queue = deque([(start, 0)])
    visited = set()
    visited.add(tuple(start))

    while queue:
        current, moves = queue.popleft()

        if current == target:
            return moves

        for i in range(3):
            for j in range(i + 1, 3):
                for k in range(1, n + 1):
                    if k not in current and graph[current[i]][current[j]] == graph[current[j]][k]:
                        new_state = list(current)
                        new_state[i] = k
                        new_state.sort()
                        if tuple(new_state) not in visited:
                            visited.add(tuple(new_state))
                            queue.append((tuple(new_state), moves + 1))

    return -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    start = tuple(map(int, data[1:4]))
    graph = [list(data[4 + i * n:4 + (i + 1) * n]) for i in range(n)]

    result = bfs(n, start, (1, 2, 3), graph)

    if result == -1:
        print(-1)
    else:
        print(result)

if __name__ == "__main__":
    main()
